package com.example.demo.weakvocabulary.service.impl;
import com.example.demo.common.exception.ResourceNotFoundException; import com.example.demo.flashcard.repository.FlashcardRepository; import com.example.demo.weakvocabulary.dto.WeakDtos.*; import com.example.demo.weakvocabulary.entity.*; import com.example.demo.weakvocabulary.exception.InvalidWeakPracticeException; import com.example.demo.weakvocabulary.repository.*; import com.example.demo.weakvocabulary.service.WeakPracticeService; import com.fasterxml.jackson.core.type.TypeReference; import com.fasterxml.jackson.databind.ObjectMapper; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.LocalDateTime; import java.util.*; import java.util.regex.Pattern;
@Service @RequiredArgsConstructor public class WeakPracticeServiceImpl implements WeakPracticeService { private final UserWeakVocabularyRepository weakRepo; private final WeakPracticeSessionRepository sessions; private final WeakPracticeItemRepository items; private final WeakPracticeAttemptRepository attempts; private final FlashcardRepository flashcards; private final ObjectMapper json=new ObjectMapper();
 @Transactional public SessionResponse start(Long uid,PracticeStartRequest r){if(r.getQuestionType()==null||r.getWeakVocabularyIds()==null||r.getWeakVocabularyIds().isEmpty())throw new InvalidWeakPracticeException("Choose a method and at least one word");if(new HashSet<>(r.getWeakVocabularyIds()).size()!=r.getWeakVocabularyIds().size())throw new InvalidWeakPracticeException("Duplicate weak vocabulary IDs are not allowed");List<UserWeakVocabulary> words=weakRepo.findAllById(r.getWeakVocabularyIds());if(words.size()!=r.getWeakVocabularyIds().size()||words.stream().anyMatch(w->!w.getUser().getId().equals(uid)||w.isWeakDeleted()))throw new InvalidWeakPracticeException("Selected weak vocabularies are invalid");WeakPracticeSession s=sessions.save(WeakPracticeSession.builder().user(words.get(0).getUser()).questionType(r.getQuestionType()).totalQuestions(words.size()).build());int n=1;for(UserWeakVocabulary w:words){WeakPracticeItem i=question(s,w,n++,r.getQuestionType());items.save(i);}return session(uid,s.getId());}
 private WeakPracticeItem question(WeakPracticeSession s,UserWeakVocabulary w,int order,WeakQuestionType t){String word=w.getFlashcard().getVocabulary(),meaning=w.getFlashcard().getMeaning(),example=w.getFlashcard().getExampleSentence();String q,answer;List<String> opts=null;if(t==WeakQuestionType.FILL_BLANK||t==WeakQuestionType.MULTIPLE_CHOICE){if(example==null||!Pattern.compile("(?i)\\b"+Pattern.quote(word)+"\\b").matcher(example).find())throw new InvalidWeakPracticeException("Flashcard '"+word+"' has no usable example sentence");q=Pattern.compile("(?i)\\b"+Pattern.quote(word)+"\\b").matcher(example).replaceAll("_____");answer=word;if(t==WeakQuestionType.MULTIPLE_CHOICE)opts=options(word,true);}else if(t==WeakQuestionType.WORD_TO_MEANING){q=word;answer=meaning;opts=options(meaning,false);}else{q=meaning;answer=word;}return WeakPracticeItem.builder().session(s).userWeakVocabulary(w).itemOrder(order).questionType(t).questionContent(q).correctAnswer(answer).optionsJson(opts==null?null:write(opts)).build();}
 private List<String> options(String correct,boolean words){LinkedHashSet<String> set=new LinkedHashSet<>();set.add(correct);for(var f:flashcards.findAll(PageRequest.of(0,40)).getContent()){String v=words?f.getVocabulary():f.getMeaning();if(v!=null&&!v.isBlank())set.add(v);if(set.size()==4)break;}List<String> list=new ArrayList<>(set);Collections.shuffle(list);return list;}
 @Transactional public AnswerResponse answer(Long uid,Long sid,Long iid,AnswerRequest r){WeakPracticeSession s=owned(uid,sid);WeakPracticeItem i=items.findByIdAndSessionId(iid,sid).orElseThrow(()->new ResourceNotFoundException("Practice item not found"));if(i.isAnswered())throw new InvalidWeakPracticeException("This question has already been answered");String given=r.getAnswer()==null?"":r.getAnswer().trim();if(i.getOptionsJson()!=null&&!read(i.getOptionsJson()).contains(given))throw new InvalidWeakPracticeException("Answer must be one of the available options");boolean ok=normalize(given).equals(normalize(i.getCorrectAnswer()));i.setAnswered(true);i.setAnsweredAt(LocalDateTime.now());items.save(i);UserWeakVocabulary w=i.getUserWeakVocabulary();w.setTotalAttempts(w.getTotalAttempts()+1);w.setLastPracticedAt(LocalDateTime.now());if(ok){w.setCorrectCount(w.getCorrectCount()+1);w.setConsecutiveWrong(0);w.setMasteryScore(Math.min(100,w.getMasteryScore()+20));s.setCorrectAnswers(s.getCorrectAnswers()+1);}else{w.setWrongCount(w.getWrongCount()+1);w.setConsecutiveWrong(w.getConsecutiveWrong()+1);w.setMasteryScore(Math.max(0,w.getMasteryScore()-20));s.setWrongAnswers(s.getWrongAnswers()+1);}weakRepo.save(w);attempts.save(WeakPracticeAttempt.builder().session(s).item(i).userWeakVocabulary(w).questionType(i.getQuestionType()).questionContent(i.getQuestionContent()).userAnswer(given).correctAnswer(i.getCorrectAnswer()).correct(ok).build());if(s.getCorrectAnswers()+s.getWrongAnswers()==s.getTotalQuestions()){s.setStatus(WeakPracticeStatus.COMPLETED);s.setCompletedAt(LocalDateTime.now());}sessions.save(s);return AnswerResponse.builder().correct(ok).correctAnswer(i.getCorrectAnswer()).correctAnswers(s.getCorrectAnswers()).wrongAnswers(s.getWrongAnswers()).completed(s.getStatus()==WeakPracticeStatus.COMPLETED).build();}
 public SessionResponse session(Long uid,Long id){WeakPracticeSession s=owned(uid,id);return SessionResponse.builder().sessionId(s.getId()).questionType(s.getQuestionType()).status(s.getStatus()).totalQuestions(s.getTotalQuestions()).correctAnswers(s.getCorrectAnswers()).wrongAnswers(s.getWrongAnswers()).questions(items.findBySessionIdOrderByItemOrder(id).stream().map(i->QuestionResponse.builder().itemId(i.getId()).itemOrder(i.getItemOrder()).questionType(i.getQuestionType()).question(i.getQuestionContent()).options(i.getOptionsJson()==null?List.of():read(i.getOptionsJson())).build()).toList()).build();} public SummaryResponse summary(Long u,Long id){WeakPracticeSession s=owned(u,id);double a=s.getTotalQuestions()==0?0:Math.round(s.getCorrectAnswers()*10000d/s.getTotalQuestions())/100d;return SummaryResponse.builder().sessionId(id).status(s.getStatus()).totalQuestions(s.getTotalQuestions()).correctAnswers(s.getCorrectAnswers()).wrongAnswers(s.getWrongAnswers()).accuracy(a).startedAt(s.getStartedAt()).completedAt(s.getCompletedAt()).build();}private WeakPracticeSession owned(Long u,Long id){return sessions.findByIdAndUserId(id,u).orElseThrow(()->new ResourceNotFoundException("Practice session not found"));}private String normalize(String s){return s.trim().replaceAll("\\s+"," ").toLowerCase(Locale.ROOT);}private String write(List<String> x){try{return json.writeValueAsString(x);}catch(Exception e){throw new IllegalStateException(e);}}private List<String> read(String s){try{return json.readValue(s,new TypeReference<>(){});}catch(Exception e){throw new IllegalStateException(e);}}}
